/* Copied from app/src/studio/AgentFigure.css (the apps don't import across each
   other); agents.test.ts checks the figures still match the house sheet.
   Agent figures. States come in as data attributes on the <svg>:
   data-state = idle | working | needs-you, data-walking when moving.
   --af-phase (0–1, per agent) offsets every loop so figures don't sync. */

/* The character sheet's colours. Ink bodies use the studio's --plan pair and
   follow the theme; these five stay put in light and dark, with a dark face.
   Coral is the sheet's own, redder than --create, which is only for needs-you. */
.agent-figure,
.agent-avatar {
  --af-cobalt: #2F64F5;
  --af-coral: #FF6A55;
  --af-marigold: #FFC023;
  --af-iris: #7D52F4;
  --af-mint: #6CD3A2;
  --af-mark: #16181D;
}

.agent-figure {
  display: block;
  overflow: visible;
  flex-shrink: 0;
  --af-bob: 2.8s;
}

.agent-figure .af-shadow { fill: var(--ink); opacity: 0.08; }
.agent-figure .af-leg line { stroke: var(--ink); stroke-width: 2.1; stroke-linecap: round; }
.agent-figure .af-leg rect { fill: var(--ink); }
.agent-avatar .aa-tile { fill: var(--soft, #F2F3F6); }

/* Legs swing from the hip: the top of each leg's own box. The body leans from
   its base, so a working figure tips forward over its feet. */
.agent-figure .af-leg { transform-box: fill-box; transform-origin: 50% 0; }
.agent-figure .af-body { transform-box: fill-box; transform-origin: 50% 100%; }
.agent-figure .af-eyes,
.agent-figure .af-badge-ring { transform-box: fill-box; transform-origin: 50% 50%; }

/* idle — a slow bob and the odd blink. */
.agent-figure .af-body {
  animation: af-bob var(--af-bob) ease-in-out infinite alternate;
  animation-delay: calc(var(--af-phase, 0) * -2.8s);
}
.agent-figure .af-eyes {
  animation: af-blink 5.2s linear infinite;
  animation-delay: calc(var(--af-phase, 0) * -5.2s);
}

/* working — leans in, small steps in place, motion lines off its shoulder. */
.agent-figure .af-motion { display: none; stroke: var(--ink); stroke-width: 1.3; stroke-linecap: round; fill: none; }
.agent-figure[data-state='working'] .af-motion { display: inline; animation: af-flicker 0.55s steps(2, jump-none) infinite; }
.agent-figure[data-state='working'] .af-leg-l,
.agent-figure[data-state='working'] .af-leg-r {
  animation: af-step 0.55s ease-in-out infinite alternate;
  animation-delay: calc(var(--af-phase, 0) * -1.1s);
}
.agent-figure[data-state='working'] .af-leg-r { animation-name: af-step-r; }
.agent-figure[data-state='working'] .af-body { animation: af-lean 0.275s ease-in-out infinite alternate; }

/* walking — a full stride; wins over whatever the state says about legs. */
.agent-figure[data-walking] .af-leg-l,
.agent-figure[data-walking] .af-leg-r {
  animation: af-stride 0.45s ease-in-out infinite alternate;
  animation-delay: calc(var(--af-phase, 0) * -0.9s);
}
.agent-figure[data-walking] .af-leg-r { animation-name: af-stride-r; }
.agent-figure[data-walking] .af-body { animation: af-bob-quick 0.225s ease-in-out infinite alternate; }

/* needs-you — the sheet's speech bubble with a "!", in the accent: orange is
   still the one colour that means a person is needed. */
.agent-figure .af-badge-bubble { fill: var(--paper); stroke: var(--create); stroke-width: 1.4; stroke-linejoin: round; }
.agent-figure .af-badge-mark { stroke: var(--create); stroke-width: 1.7; stroke-linecap: round; }
.agent-figure .af-badge-dot { fill: var(--create); }
.agent-figure .af-badge-ring { fill: none; stroke: var(--create); stroke-width: 1.4; animation: af-ping 1.8s var(--ease, ease-out) infinite; }

@keyframes af-bob { from { transform: translateY(0); } to { transform: translateY(-1.6px); } }
@keyframes af-bob-quick { from { transform: translateY(0); } to { transform: translateY(-1.2px); } }
@keyframes af-lean { from { transform: rotate(8deg) translateY(0); } to { transform: rotate(8deg) translateY(-1.2px); } }
@keyframes af-step { from { transform: rotate(-9deg); } to { transform: rotate(9deg); } }
@keyframes af-step-r { from { transform: rotate(9deg); } to { transform: rotate(-9deg); } }
@keyframes af-stride { from { transform: rotate(-20deg); } to { transform: rotate(20deg); } }
@keyframes af-stride-r { from { transform: rotate(20deg); } to { transform: rotate(-20deg); } }
@keyframes af-blink { 0%, 93%, 100% { transform: scaleY(1); } 95% { transform: scaleY(0.1); } }
@keyframes af-flicker { from { opacity: 1; } to { opacity: 0.35; } }
@keyframes af-ping { 0% { transform: scale(1); opacity: 0.5; } 80%, 100% { transform: scale(1.8); opacity: 0; } }

@media (prefers-reduced-motion: reduce) {
  .agent-figure *, .agent-figure { animation: none !important; }
  .agent-figure .af-badge-ring { display: none; }
  /* Still reads as working without motion. */
  .agent-figure[data-state='working'] .af-body { transform: rotate(8deg); }
}

/* Ink bodies (Nell, Jude) follow the theme, so in dark mode they turn light and
   can vanish on a light ground (a paper page, a report). An outline in the
   page's own ink keeps them visible on any ground. Coloured bodies need none. */
.agent-figure .af-body [fill='var(--plan)'] {
  stroke: var(--af-edge, var(--ink));
  stroke-width: 2.4;
  stroke-linejoin: round;
  paint-order: stroke fill;
}
